pts={(2,0),(2,1),(2,4),(2,5),(3,0),(4,2),(4,3),(4,4),(4,5),(5,5),(6,0),(6,5),(7,0),(7,5),(8,0),(8,3),(8,5)}
adds=set()
for r in range(19):
 cs=sorted(c for rr,c in pts if rr==r)
 if len(cs)>1:
  adds.update((r,c) for c in range(cs[0],cs[-1]+1) if (r,c) not in pts)
for c in range(9):
 rs=sorted(r for r,cc in pts if cc==c)
 if len(rs)>1:
  adds.update((r,c) for r in range(rs[0],rs[-1]+1) if (r,c) not in pts)
print(sorted(adds))
grid=[[4]*9 for _ in range(19)]
for r,c in pts:grid[r][c]=3
for r,c in adds:grid[r][c]=2
print('\n'.join(str(row) for row in grid))
